int fd = /* open file descriptor */;
off_t offset = 1048576; // 1MB
off_t len = 4096;      // 1 page

// Allocate space without changing the logical file size (i_size)
int alloc_ret = fallocate(fd, FALLOC_FL_KEEP_SIZE, 0, offset);

// Punch a hole: Deallocate disk space (offset to offset + len)
int hole_ret = fallocate(fd, FALLOC_FL_PUNCH_HOLE | FALLOC_FL_KEEP_SIZE,
                         offset, len);

// Zero out a specific range
int zero_ret = fallocate(fd, FALLOC_FL_ZERO_RANGE,
                         offset + len, 4096);

if (alloc_ret == -1 || hole_ret == -1 || zero_ret == -1) {
    /* Handle errors (ENOSPC, EOPNOTSUPP, EBADF) */
}
